{
  "implementation": "def solve(case):
    nodes = case['nodes']
    required_symbols = set(case['required_symbols'])

    node_map = {node['id']: node for node in nodes}
    children_map = {node['id']: [] for node in nodes}
    for node in nodes:
        parent = node['parent']
        if parent is not None:
            children_map[parent].append(node['id'])

    root_id = None
    for node in nodes:
        if node['parent'] is None:
            root_id = node['id']
            break
    if root_id is None:
        raise ValueError("No root node found")

    retained = set(node_map.keys())

    symbol_count = {}
    for node in nodes:
        sym = node['symbol']
        if sym in required_symbols:
            symbol_count[sym] = symbol_count.get(sym, 0) + 1

    sorted_nodes = sorted(nodes, key=lambda n: (-n['depth'], n['id']))

    removed = []
    for node in sorted_nodes:
        nid = node['id']
        if not node['removable']:
            continue
        if nid not in retained:
            continue
        has_retained_child = any(child_id in retained for child_id in children_map.get(nid, []))
        if has_retained_child:
            continue
        sym = node['symbol']
        if sym in required_symbols and symbol_count.get(sym, 0) == 1:
            continue
        retained.remove(nid)
        if sym in required_symbols:
            symbol_count[sym] -= 1
        removed.append(nid)

    retained_sorted = sorted(retained)
    return {
        "removed_node_ids": removed,
        "retained_node_ids": retained_sorted
    }"
}
